#include <nds.h>
#include <fat.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#define N 64
#define LEN 180
static PrintConsole top, bottom;
static char names[N][32], draft[N][LEN], dims[N][24];
static int count=0, sel=0, mode=0, key=0, upper=0, scroll=0, storage=0, dim=0;
static char input[LEN], notice[40];
static int narrator=0;
static const char *dimensions[]={"Acirema","Dimension X","Underworld","Avlique","Northwood","Storybend","Heaven"};
static const char *keys[]={"qwertyuiop","asdfghjkl ","zxcvbnm,.?","1234567890","!'-:;@()/+"};
static void save(void){if(!storage)return; FILE*f=fopen("/Dimensionz/contacts.dat","wb");if(!f){strcpy(notice,"Save failed");return;} fwrite(&count,sizeof count,1,f);fwrite(names,sizeof names,1,f);fwrite(dims,sizeof dims,1,f);fwrite(draft,sizeof draft,1,f);if(fclose(f))strcpy(notice,"Save failed");}
static void load(void){FILE*f=fopen("/Dimensionz/contacts.dat","rb");if(!f)return; if(fread(&count,sizeof count,1,f)!=1||count<0||count>N||fread(names,sizeof names,1,f)!=1||fread(dims,sizeof dims,1,f)!=1||fread(draft,sizeof draft,1,f)!=1)count=0;fclose(f);for(int i=0;i<count;i++){names[i][31]=0;dims[i][23]=0;draft[i][LEN-1]=0;}}
static void path(char*p){sprintf(p,"/Dimensionz/chat%02d.txt",sel);}
static void append(char side){if(!input[0])return;if(!storage){strcpy(notice,"SD unavailable; not saved");return;}char p[64];path(p);FILE*f=fopen(p,"a");if(!f){strcpy(notice,"Cannot open chat file");return;}time_t now=time(NULL);struct tm*t=localtime(&now);char stamp[32]="Unknown time";if(t)strftime(stamp,sizeof stamp,"%m/%d/%y %H:%M",t);int ok;if(side=='N'){ok=fprintf(f,"Narration %s\n",stamp);for(int j=0;ok>=0&&input[j];){int len=strlen(input+j);if(len>31)len=31;ok=fprintf(f,"%*s%.*s\n",(31-len)/2,"",len,input+j);j+=len;}}else ok=fprintf(f,"%c %s\n%s\n",side,stamp,input);int closed=fclose(f);if(ok<0||closed){strcpy(notice,"Save failed");return;}input[0]=0;draft[sel][0]=0;save();scroll=0;strcpy(notice,"Saved to SD");}
static void add(char c){size_t n=strlen(input);if(n<LEN-1){input[n]=c;input[n+1]=0;}}
static void back(void){size_t n=strlen(input);if(n)input[n-1]=0;}
static void leave(void){if(mode==1||mode==3){strcpy(draft[sel],input);save();}mode=0;input[0]=0;scroll=0;}
static void openchat(void){if(!count)return;mode=1;narrator=0;strcpy(input,draft[sel]);scroll=0;}
static void draw(void){consoleSelect(&top);consoleClear();iprintf("\x1b[35mDIMENSIONZ / DSi\x1b[0m\n");if(mode==0){iprintf("Fictional chat diary\n\n");int start=sel>8?sel-8:0;for(int i=start;i<count&&i<start+9;i++)iprintf("%c %.19s\n  %.24s\n",i==sel?'>':' ',names[i],dims[i]);if(!count)iprintf("No chats yet. Press X.\n");}else if(mode==4){iprintf("Rename contact\nName: %.28s\nSTART: save\n",input);}else if(mode==2){iprintf("New contact\nName: %.28s\nDimension: %s\nL/R: change dimension\nSTART: create contact\n",input,dimensions[dim]);}else{iprintf("%.20s\n%s\n-------------------------------\n",names[sel],dims[sel]);char p[64],line[256],ring[18][33];int total=0;path(p);FILE*f=storage?fopen(p,"r"):NULL;if(f){while(fgets(line,sizeof line,f)){line[strcspn(line,"\r\n")]=0;int n=strlen(line);if(!n){ring[total++%18][0]=0;}for(int j=0;j<n;j+=31){snprintf(ring[total++%18],33,"%.31s",line+j);}}fclose(f);} /* retrieve older pages with a second pass */
if(scroll>total-18)scroll=total>18?total-18:0;if(scroll&&total>18){int end=total-scroll;if(end<1)end=1;int begin=end>18?end-18:0;int idx=0;f=fopen(p,"r");if(f){while(fgets(line,sizeof line,f)){line[strcspn(line,"\r\n")]=0;int n=strlen(line);for(int j=0;j<n||(!n&&j==0);j+=31){if(idx>=begin&&idx<end)iprintf("%.31s\n",line+j);idx++;}}fclose(f);}}else{int begin=total>18?total-18:0;for(int i=begin;i<total;i++)iprintf("%s\n",ring[i%18]);}if(!total)iprintf("No messages yet.\n");}
consoleSelect(&bottom);consoleClear();if(mode==0){iprintf("\x1b[35mCHATS\x1b[0m\n\nD-pad: choose chat\nA: open\nX: new contact\nY: rename contact\n\n%s\n",storage?"SD saving enabled":"SD unavailable");return;}iprintf("%s\n",mode==2?"CONTACT NAME":mode==4?"RENAME CONTACT":mode==3?"SCROLL MODE":narrator?"NARRATOR ON - L/R POST":"L SEND / R RECEIVE");int n=strlen(input);iprintf("%.31s\n",input+(n>62?n-62:0));if(n>31)iprintf("%.31s\n",input+n-31);else iprintf("\n");for(int r=0;r<5;r++){for(int c=0;c<10;c++){char ch=keys[r][c];if(upper&&ch>='a'&&ch<='z')ch-=32;iprintf("%s%c%s",key==r*10+c?"\x1b[35m[":" ",ch,key==r*10+c?"]\x1b[0m":" ");}iprintf("\n\n");}iprintf("[ SHIFT ]\nX Space   B Delete\nY: %s   Tap Shift below\nSELECT: scroll / type\nSTART: %s\n%s\n",mode==1?"Narrator":"Shift",mode==2||mode==4?"save contact":"chats",notice);}
int main(void){videoSetMode(MODE_0_2D);videoSetModeSub(MODE_0_2D);vramSetBankA(VRAM_A_MAIN_BG);vramSetBankC(VRAM_C_SUB_BG);consoleInit(&top,0,BgType_Text4bpp,BgSize_T_256x256,31,0,true,true);consoleInit(&bottom,0,BgType_Text4bpp,BgSize_T_256x256,31,0,false,true);lcdMainOnTop();storage=fatInitDefault();if(storage){mkdir("/Dimensionz",0777);load();}draw();while(1){swiWaitForVBlank();scanKeys();int k=keysDown();if(!k)continue;if(mode==0){if(k&KEY_UP&&sel>0)sel--;if(k&KEY_DOWN&&sel+1<count)sel++;if(k&KEY_A)openchat();if(k&KEY_X&&count<N){mode=2;input[0]=0;dim=1;}if(k&KEY_Y&&count){mode=4;strcpy(input,names[sel]);}}else if(mode==3){if(k&KEY_UP)scroll+=3;if(k&KEY_DOWN){scroll-=3;if(scroll<0)scroll=0;}if(k&KEY_SELECT)mode=1;if(k&KEY_START)leave();}else{if(k&KEY_LEFT)key=(key+49)%50;if(k&KEY_RIGHT)key=(key+1)%50;if(k&KEY_UP)key=(key+40)%50;if(k&KEY_DOWN)key=(key+10)%50;if(k&KEY_Y){if(mode==1)narrator=!narrator;else upper=!upper;}if(k&KEY_X)add(' ');if(k&KEY_B)back();if(k&KEY_TOUCH){touchPosition t;touchRead(&t);int r=(t.py-24)/16,c=t.px/24;if(t.py>=104&&t.py<112){upper=!upper;}else if(t.py>=24&&r<5&&c<10){key=r*10+c;k|=KEY_A;}}if(k&KEY_A){char ch=keys[key/10][key%10];if(upper&&ch>='a'&&ch<='z')ch-=32;add(ch);}if(mode==1){if(k&KEY_L)append(narrator?'N':'>');if(k&KEY_R)append(narrator?'N':'<');if(k&KEY_SELECT)mode=3;if(k&KEY_START)leave();}else{if(k&KEY_L)dim=(dim+6)%7;if(k&KEY_R)dim=(dim+1)%7;if(k&KEY_START&&input[0]){if(mode==2){sel=count++;snprintf(dims[sel],24,"%s",dimensions[dim]);}snprintf(names[sel],32,"%.31s",input);save();mode=0;input[0]=0;}}}draw();}return 0;}
